    /// The icon shared/ui/Icons.tsx exports as `name`, or one of the phone's own
    /// drawn icons by its key; `filled` asks for the solid version of a line icon.
    static func named(_ name: String, filled: Bool = false) -> IconDef? {
        if filled {
            switch name {
            case "IconAgent": return agent
            default: return nil
            }
        }
        switch name {
        case "Logo": return logo
        case "IconActivity": return activity
        case "IconAgent": return agentLine
        case "IconAgents": return agents
        case "IconArrowDown": return arrowDown
        case "IconArrowUp": return arrowUp
